module.exports = function(RED) {
    function ATConfigNode(n) {
        RED.nodes.createNode(this, n);
        this.username = n.username;
        this.apiKey = n.apiKey;
        this.environment = n.environment || 'sandbox';
        this.defaultCallerId = n.defaultCallerId;
        this.defaultLanguage = n.defaultLanguage || 'en';
        this.defaultTimeout = parseInt(n.defaultTimeout) || 30;

        // Make globally accessible via RED
        RED.kumva = RED.kumva || {};
        RED.kumva.atConfig = this;
    }
    RED.nodes.registerType("at-config", ATConfigNode);
};